  /* ---------------------------------------------------------------------- */
  /* 6. MODÈLE DE RADIATION (Hassler et al. 2014)                           */
  /* ---------------------------------------------------------------------- */
  /* Mesure réelle de référence : RAD/MSL, cratère Gale, surface, GCR pur.
       • Dose absorbée           0,210 ± 0,040 mGy/jour
       • Équivalent de dose      0,640 ± 0,120 mSv/jour
       • Site à −4,4 km MOLA, colonne atmosphérique ≈ 21 g/cm²
     Modèle (clairement identifié comme tel) :
       D(h) = D_ref · exp((h − h_ref)/H_att) · (1 / SVF^κ) · f_solaire
     avec H_att = 15 km (échelle d'atténuation GCR verticale à Jezero, ordre de
     grandeur cohérent avec les colonnes ~16–17 g/cm² attendues à −2,57 km),
     SVF = facteur d'ouverture du ciel du DTM (blindage topographique),
     κ = 0,35 (exposant d'efficacité de blindage), f_solaire = scénario SEP.
     INCERTITUDE : ±19 % (1σ) sur la dose absorbée de référence ; le modèle ne
     remplace pas une mesure et n'intègre ni le cycle solaire réel ni les SEP.  */

  const RADIATION = {
    refLat: 18.4446, refLon: 77.4509,   // référence de projection d'altitude
    refElev: -2570.0,

    /** Colonne atmosphérique approchée (g/cm²) — modèle exponentiel. */
    column(heightM) {
      const hRef = CFG.galGaleAlt, cRef = CFG.galColumn, scaleH = CFG.radScaleKm * 1000;
      return cRef * Math.exp(clamp((heightM - hRef) / scaleH, -3, 3));
    },

    /** Équivalent de dose instantané (mSv/h) en un point, ou null hors grille. */
    rateAt(lat, lon) {
      const t = terrainAt(lat, lon);
      const elev = t ? t.elev : null;
      if (elev === null) return null;
      const svf = clamp(t.svf === null ? 1 : t.svf, 0.75, 1);
      const att = Math.exp(clamp((elev - CFG.galGaleAlt) / (CFG.radScaleKm * 1000), -3, 3));
      const shield = Math.pow(1 / svf, 0.35);
      const mSvPerDay = CFG.galDoseEq * att * shield * CFG.solarFactor;
      return {
        mSvPerDay,
        mGyPerDay: mSvPerDay * (CFG.galDose / CFG.galDoseEq),
        column: this.column(elev),
        svf, elev
      };
    },

    /** Facteur multiplicatif vs mesure de référence (pour la carte thermique). */
    factorAt(lat, lon) {
      const r = this.rateAt(lat, lon);
      return r ? r.mSvPerDay / CFG.galDoseEq : null;
    }
  };

  /* ---------------------------------------------------------------------- */
  /* 7. MODÈLE MÉTABOLIQUE ET CONSOMMABLES (BVAD)                           */
  /* ---------------------------------------------------------------------- */
  /* Le coût métabolique instantané est modulé par la pente et la rugosité :
       P = P_nom · (1 + k_slope·sin θ + k_tri·TRI + k_dune·[Aeb])
     Les coefficients k sont des hypothèses ergonomiques de simulation
     (ordre de grandeur de la littérature sur la marche en charge) — ils ne
     sont pas des mesures martiennes.                                        */

  const METAB = {
    slopeFactor: 1.90,     // par unité de sin(pente)
    downSlopeFactor: 0.55, // descente : coût réduit
    triFactor: 0.55,       // par mètre de TRI
    duneFactor: 0.85,      // sable
    walkSpeedFor(slope, tri) {
      // Réduction de vitesse en terrain difficile (marche en combinaison).
      const s = Math.abs(slope || 0);
      const v = CFG.walkSpeed * (1 - 0.022 * s) * (1 / (1 + 0.30 * (tri || 0)));
      return clamp(v, 0.18, CFG.walkSpeed);
    },
    /** Puissance métabolique (W) pour un point de terrain. */
    powerW(t) {
      const sl = t ? (t.slope || 0) : 0;
      const tri = t ? (t.tri || 0) : 0;
      const dune = t && t.unit === 'Aeb' ? 1 : 0;
      const sinS = Math.sin(rad(sl));
      const slopeCost = sinS >= 0 ? this.slopeFactor * sinS : this.downSlopeFactor * Math.abs(sinS) * 0.5;
      const f = 1 + slopeCost + this.triFactor * tri + this.duneFactor * dune;
      return CFG.energyNominal * 1e6 / 3600 * f;   // MJ/h → W
    }
  };

  /* ---------------------------------------------------------------------- */
  /* 8. GRILLE DE NAVIGATION (A*)                                            */
  /* ---------------------------------------------------------------------- */
  const NAV = {
    blocked: null,          // Uint8Array : 1 = infranchissable
    linkSpeed: null,        // cache des vitesses par lien (8 directions)
    stats: { blockedCount: 0 }
  };

  function buildBlockedMap() {
    const N = T.H * T.W;
    NAV.blocked = new Uint8Array(N);
    let n = 0;
    for (let i = 0; i < N; i++) {
      const s = T.slope[i], tri = T.tri[i] / 10;
      const isDune = CFG.avoidDunes && isDuneCell(i);
      const b = (s > CFG.slopeLimit) || (tri > CFG.triLimit) || isDune;
      if (b) { NAV.blocked[i] = 1; n++; }
    }
    NAV.stats.blockedCount = n;
    NAV.linkSpeed = null;
  }

  function isDuneCell(i) {
    const r = (i / T.W) | 0, c = i - r * T.W;
    const code = T.geo[r * T.geoW + c];
    const u = T.units[code - 1];
    return u ? u.s === 'Aeb' : false;
  }

  /** Coût d'un déplacement élémentaire (grille) — C = 1 + α·pente + β·rugosité + γ·dune. */
  function stepCost(iFrom, iTo, diag) {
    const r = (iTo / T.W) | 0, c = iTo - r * T.W;
    const slope = T.slope[iTo], tri = T.tri[iTo] / 10;
    const code = T.geo[r * T.geoW + c];
    const u = T.units[code - 1];
    const dune = u && u.s === 'Aeb' ? 1 : 0;
    const lengthM = diag ? T.stepM * Math.SQRT2 : T.stepM;
    const c1 = 1 + CFG.alpha * Math.abs(Math.sin(rad(slope))) + CFG.beta * tri + CFG.gammaDune * dune;
    return lengthM * c1;
  }

  const DIRS = [
    [-1, 0, false], [1, 0, false], [0, -1, false], [0, 1, false],
    [-1, -1, true], [-1, 1, true], [1, -1, true], [1, 1, true]
  ];

  /** A* : retourne un tableau d'indices de grille start→goal, ou {error}. */
  function astar(startIdx, goalIdx) {
    if (!NAV.blocked) buildBlockedMap();
    const H = T.H, W = T.W, N = H * W;
    if (NAV.blocked[startIdx]) return { error: 'blocked-start' };
    // objectif bloqué : chercher la cellule libre la plus proche (rayon ≤ 6)
    let goal = goalIdx;
    if (NAV.blocked[goal]) {
      const gr = (goal / W) | 0, gc = goal - gr * W;
      let best = -1, bestD = Infinity;
      for (let dr = -6; dr <= 6; dr++) for (let dc = -6; dc <= 6; dc++) {
        const rr = gr + dr, cc = gc + dc;
        if (rr < 0 || rr >= H || cc < 0 || cc >= W) continue;
        const ii = rr * W + cc;
        if (NAV.blocked[ii]) continue;
        const d = dr * dr + dc * dc;
        if (d < bestD) { bestD = d; best = ii; }
      }
      if (best < 0) return { error: 'blocked-goal' };
      goal = best;
    }

    const gScore = new Float32Array(N).fill(Infinity);
    const cameFrom = new Int32Array(N).fill(-1);
    const closed = new Uint8Array(N);
    const goalR = (goal / W) | 0, goalC = goal - goalR * W;
    const heur = i => {
      const r = (i / W) | 0, c = i - r * W;
      const dr = Math.abs(r - goalR), dc = Math.abs(c - goalC);
      return (dr + dc + (Math.SQRT2 - 2) * Math.min(dr, dc)) * T.stepM;
    };
    const open = new MinHeap();
    gScore[startIdx] = 0;
    open.push(startIdx, heur(startIdx));

    let expanded = 0;
    while (open.size) {
      const cur = open.pop();
      if (cur === goal) break;
      if (closed[cur]) continue;
      closed[cur] = 1;
      expanded++;
      const r = (cur / W) | 0, c = cur - r * W;
      for (let k = 0; k < 8; k++) {
        const [dr, dc, diag] = DIRS[k];
        const rr = r + dr, cc = c + dc;
        if (rr < 0 || rr >= H || cc < 0 || cc >= W) continue;
        const ni = rr * W + cc;
        if (NAV.blocked[ni] || closed[ni]) continue;
        // Pas de « coupe de coin » sur obstacles diagonaux
        if (diag && (NAV.blocked[r * W + cc] || NAV.blocked[rr * W + c])) continue;
        const ng = gScore[cur] + stepCost(cur, ni, diag);
        if (ng < gScore[ni]) {
          gScore[ni] = ng;
          cameFrom[ni] = cur;
          open.push(ni, ng + heur(ni));
        }
      }
      if (expanded > 260000) return { error: 'limit' };
    }
    if (cameFrom[goal] === -1 && goal !== startIdx) return { error: 'no-path' };
    const path = [];
    let p = goal;
    while (p !== -1) { path.push(p); p = cameFrom[p]; }
    path.reverse();
    return { path, cost: gScore[goal], snapped: goal !== goalIdx };
  }

  /** Tas binaire min (clé flottante, valeur entière). */
  class MinHeap {
    constructor() { this.k = []; this.v = []; }
    get size() { return this.v.length; }
    push(val, key) {
      this.k.push(key); this.v.push(val);
      let i = this.v.length - 1;
      while (i > 0) {
        const p = (i - 1) >> 1;
        if (this.k[p] <= this.k[i]) break;
        this.swap(i, p); i = p;
      }
    }
    pop() {
      const top = this.v[0];
      const lk = this.k.pop(), lv = this.v.pop();
      if (this.v.length) {
        this.k[0] = lk; this.v[0] = lv;
        let i = 0;
        for (;;) {
          const l = 2 * i + 1, r = l + 1;
          let m = i;
          if (l < this.v.length && this.k[l] < this.k[m]) m = l;
          if (r < this.v.length && this.k[r] < this.k[m]) m = r;
          if (m === i) break;
          this.swap(i, m); i = m;
        }
      }
      return top;
    }
    swap(a, b) {
      const tk = this.k[a]; this.k[a] = this.k[b]; this.k[b] = tk;
      const tv = this.v[a]; this.v[a] = this.v[b]; this.v[b] = tv;
    }
  }

  /** Décode une séquence d'indices en polyligne {lat, lon, elev, slope, tri, unit}. */
  function pathToLatLngs(path) {
    return path.map(i => {
      const r = (i / T.W) | 0, c = i - r * T.W;
      const ll = rcLatLon(r, c);
      const code = T.geo[r * T.geoW + c];
      const u = T.units[code - 1];
      return {
        lat: ll.lat, lon: ll.lon,
        elev: T.elev[i], slope: T.slope[i], tri: T.tri[i] / 10,
        unit: u ? u.s : null
      };
    });
  }

  /** Analyse détaillée d'un itinéraire : distance, durée, O2, énergie, dénivelé. */
  function analysePath(pts, opts) {
    const o = Object.assign({ dwellSec: 0, startO2: CFG.o2Total, startEnergy: CFG.energyTotal }, opts || {});
    let dist = 0, durSec = 0, o2 = 0, energy = 0, climb = 0, descent = 0;
    let maxSlope = 0, sumSlope = 0, maxTri = 0, sumTri = 0, duneDist = 0;
    for (let i = 1; i < pts.length; i++) {
      const a = pts[i - 1], b = pts[i];
      const segM = distM(a.lat, a.lon, b.lat, b.lon);
      dist += segM;
      const slope = (a.slope + b.slope) / 2, tri = (a.tri + b.tri) / 2;
      const v = METAB.walkSpeedFor(slope, tri);
      const dt = segM / v;
      durSec += dt;
      const tMid = { slope, tri, unit: b.unit };
      const pW = METAB.powerW(tMid);
      energy += pW * dt;
      o2 += (CFG.o2MetabolicNominal + CFG.o2Leak) * dt / 3600;
      const dz = b.elev - a.elev;
      if (dz > 0) climb += dz; else descent -= dz;
      maxSlope = Math.max(maxSlope, slope);
      sumSlope += slope * segM;
      maxTri = Math.max(maxTri, tri);
      sumTri += tri * segM;
      if (b.unit === 'Aeb') duneDist += segM;
    }
    const scienceO2 = (CFG.o2MetabolicNominal + CFG.o2Leak) * o.dwellSec / 3600;
    const scienceEnergy = CFG.energyNominal * 1e6 / 3600 * o.dwellSec;
    return {
      distM: dist,
      durSec: durSec + o.dwellSec,
      walkSec: durSec,
      o2kg: o2 + scienceO2,
      o2Science: scienceO2,
      energyMJ: (energy + scienceEnergy) / 1e6,
      energyScienceMJ: scienceEnergy / 1e6,
      climb, descent,
      maxSlope, meanSlope: dist ? sumSlope / dist : 0,
      maxTri, meanTri: dist ? sumTri / dist : 0,
      duneDist
    };
  }

  const pointFromLatLon = (lat, lon) => {
    const t = terrainAt(lat, lon);
    return { lat, lon, elev: t ? t.elev : null, slope: t ? t.slope : 0, tri: t ? t.tri : 0, unit: t ? t.unit : null };
  };

  /** Itinéraire complet : départ → (destination) → base, avec analyses. */
  function computeRoutes(start, dest, base) {
    if (!T.ready) return { error: 'terrain' };
    const s = cellAt(start.lat, start.lon), d = cellAt(dest.lat, dest.lon), b = cellAt(base.lat, base.lon);
    if (!insideGrid(start.lat, start.lon) || !insideGrid(dest.lat, dest.lon) || !insideGrid(base.lat, base.lon)) {
      return { error: 'outside' };
    }
    const out = astar(s.i, d.i);
    if (out.error) return { error: out.error };
    const ret = astar(d.i, b.i);
    if (ret.error) return { error: 'return-' + ret.error };
    const ptsOut = pathToLatLngs(out.path);
    const ptsRet = pathToLatLngs(ret.path);
    const aOut = analysePath(ptsOut, { dwellSec: CFG.scienceDwell });
    const aRet = analysePath(ptsRet);
    return {
      outbound: { pts: ptsOut, analysis: aOut, cost: out.cost, snapped: out.snapped },
      ret: { pts: ptsRet, analysis: aRet, cost: ret.cost, snapped: ret.snapped },
      total: {
        distM: aOut.distM + aRet.distM,
        durSec: aOut.durSec + aRet.durSec,
        o2kg: aOut.o2kg + aRet.o2kg,
        energyMJ: aOut.energyMJ + aRet.energyMJ,
        climb: aOut.climb + aRet.climb
      }
    };
  }

  /* ---------------------------------------------------------------------- */
  /* 9. ÉTAT DE L'APPLICATION                                               */
  /* ---------------------------------------------------------------------- */
  const S = {
    mode: 'manuel',                    // 'manuel' | 'simulation'
    start: { lat: 18.45277, lon: 77.40825 },
    dest: { lat: 18.45879, lon: 77.40601 },
    base: { lat: 18.4468, lon: 77.4416 },
    astronaut: { lat: 18.45277, lon: 77.40825 },
    customPOIs: [],
    pickMode: null,                    // 'start' | 'dest' | 'base' | 'astro' | 'poi'
    layers: {
      basemap: 'ctx',                  // 'ctx' | 'hirise' | 'viking' | 'mola' | 'off'
      hypsometry: true,
      hillshade: true,
      slope: false,
      roughness: false,
      geology: false,
      radiation: false,
      traverse: true,
      scienceZones: true,
      markers: true,
      grid: true
    },
    routes: null,
    routeErr: null,
    sim: {
      state: 'idle',                   // idle | running | paused | arrived | returned | done
      t: 0,                            // secondes simulées
      timeScale: CFG.timeScaleDefault,
      o2: CFG.o2Total,
      energy: CFG.energyTotal,
      radMgy: 0, radMsv: 0,
      pos: null,
      leg: 'outbound',                 // outbound | science | return
      lastTick: 0,
      phase: 'Prêt',
      log: []
    },
    ui: { panel: 'mission' },
    net: { tiles: 0, tilesErr: 0, lastTile: null },
    suivis: []
  };

  /* ---------------------------------------------------------------------- */
  /* 10. CHARGEMENT DE LEAFLET (CDN + repli)                                */
  /* ---------------------------------------------------------------------- */
  const LEAFLET_URLS = [
    { css: 'https://unpkg.com/leaflet@1.9.4/dist/leaflet.css', js: 'https://unpkg.com/leaflet@1.9.4/dist/leaflet.js' },
    { css: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.css', js: 'https://cdnjs.cloudflare.com/ajax/libs/leaflet/1.9.4/leaflet.js' },
    { css: 'https://cdn.jsdelivr.net/npm/leaflet@1.9.4/dist/leaflet.css', js: 'https://cdn.jsdelivr.net/npm/leaflet@1.9.4/dist/leaflet.js' }
  ];

  function loadScript(src) {
    return new Promise((resolve, reject) => {
      const sc = document.createElement('script');
      sc.src = src; sc.async = true;
      sc.onload = () => resolve(src);
      sc.onerror = () => reject(new Error('échec ' + src));
      document.head.appendChild(sc);
    });
  }
  function loadCSS(href) {
    return new Promise(resolve => {
      const l = document.createElement('link');
      l.rel = 'stylesheet'; l.href = href;
      l.onload = l.onerror = () => resolve(href);
      document.head.appendChild(l);
    });
  }

  async function loadLeaflet() {
    if (window.L && window.L.map) return 'déjà présent';
    for (const set of LEAFLET_URLS) {
      try {
        await loadCSS(set.css);
        await loadScript(set.js);
        if (window.L && window.L.map) return set.js;
      } catch (e) { /* CDN suivant */ }
    }
    throw new Error('Leaflet introuvable (CDN bloqués)');
  }

